ROOT = Path(__file__).resolve().parents[1]
LETTERS = 'ABCDE'
# Case endings written onto the noun (never "туулай-ны"; a hyphen belongs only after abbreviations and numbers).
GENITIVE = {'туулай': 'туулайн', 'далайн гахай': 'далайн гахайн', 'хонь': 'хонины'}
ACCUSATIVE = {'Тайга': 'тайгыг', 'Хуурай хээр': 'хуурай хээрийг', 'Цөл': 'цөлийг'}

def half_up(value, places=2):
    """Round half up as taught in school (0.735 -> 0.74, 1.075 -> 1.08), not the binary float's 0.73 / 1.07."""
    return format(Decimal(repr(round(value, 10))).quantize(Decimal(1).scaleb(-places), rounding=ROUND_HALF_UP), 'f')

def nums(values):
    """A list of numbers as printed for students: 55, 98, 47 (not [55.0, 98.0, 47.0])."""
    return ', '.join(f'{v:g}' for v in values)

def write_json(path, value):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value, ensure_ascii=False, indent=2)+'\n', encoding='utf-8')

def svg(body, width=900, height=340):
    return (f'<svg xmlns="http://www.w3.org/2000/svg" width="{width}" height="{height}" viewBox="0 0 {width} {height}">'
            '<rect width="100%" height="100%" fill="white"/>'
            '<style>text{font:19px Arial,sans-serif;fill:#111}path,line,ellipse,circle,rect{stroke-linejoin:round}</style>'
            +body+'</svg>')

def table(headers, rows):
    cells=[headers]+rows
    columns=len(headers)
    width=max(900,columns*200)
    out=''
    y=20
    for i,row in enumerate(cells):
        colwidth=(width-40)/columns
        wrapped=[textwrap.wrap(str(value),width=max(8,int((colwidth-20)/9)),break_long_words=True) or [''] for value in row]
        rh=max(52,18+max(len(x) for x in wrapped)*25)
        for j,value in enumerate(row):
            x=20+j*(width-40)/columns
            out+=f'<rect x="{x}" y="{y}" width="{colwidth}" height="{rh}" fill="{"#eef1f5" if i==0 else "white"}" stroke="#555"/>'
            for k,line in enumerate(wrapped[j]):out+=f'<text x="{x+10}" y="{y+30+k*25}" style="font-size:17px">{escape(line)}</text>'
        y+=rh
    return svg(out,width,y+20)

def plot(series, xlabels, ylabel='Хэмжээ', xlabel='Хугацаа', maximum=None):
    maximum=maximum or max(max(values) for _,values in series)*1.15
    colors=['#111','#777','#315d8a']
    out=f'<text x="25" y="30">{escape(ylabel)}</text><path d="M80 55 V290 H690" fill="none" stroke="#111" stroke-width="2"/>'
    for k in range(6):
        v=maximum*k/5; y=290-220*k/5
        out+=f'<line x1="75" y1="{y}" x2="690" y2="{y}" stroke="#ddd"/><text x="10" y="{y+6}">{v:.1f}</text>'
    for i,label in enumerate(xlabels):
        x=80+i*600/max(1,len(xlabels)-1)
        out+=f'<text x="{x-12}" y="316">{escape(str(label))}</text>'
    for k,(name,values) in enumerate(series):
        points=' '.join(f'{80+i*600/max(1,len(values)-1)},{290-v/maximum*220}' for i,v in enumerate(values))
        out+=f'<polyline points="{points}" fill="none" stroke="{colors[k]}" stroke-width="3" stroke-dasharray="{"8 4" if k==1 else "none"}"/>'
        out+=f'<text x="720" y="{80+k*35}">{escape(name)}</text>'
    out+=f'<text x="290" y="350">{escape(xlabel)}</text>'
    return svg(out,950,380)

def scheme(nodes):
    # A labelled process flow; numeric labels are what the learner must interpret.
    out=''
    for i,text in enumerate(nodes):
        x=25+(i%3)*290;y=25+(i//3)*115
        out+=f'<rect x="{x}" y="{y}" width="255" height="75" rx="8" fill="#f5f6f8" stroke="#111"/>'
        out+=f'<text x="{x+12}" y="{y+30}">{i+1}</text><text x="{x+12}" y="{y+58}">{escape(text)}</text>'
        if i%3<2 and i+1<len(nodes):out+=f'<path d="M{x+258} {y+38} h25 l-8 -6 m8 6 l-8 6" fill="none" stroke="#111"/>'
    return svg(out,900,45+math.ceil(len(nodes)/3)*115)

