def make(stem, correct, wrong, explanation, visual=None, evidence=None):
    assert len(wrong)==4 and len(set([correct]+wrong))==5, (stem,correct,wrong)
    return {'prompt':stem,'correctText':str(correct),'wrong':[str(x) for x in wrong],
            'explanation':explanation,'visual':visual,'calculation':evidence}

def numeric(stem, value, explanation, visual=None, evidence=None):
    value=round(value,4)
    top=1 if 0<value<1 else 100 if 'хувь' in stem else None
    ok=lambda v:v>=0 and v!=value and (top is None or v<=top)
    below=[v for v in dict.fromkeys(round(v,4) for v in [value/2,value-5,value-1,value/3,value-10]) if ok(v) and v<value]
    above=[v for v in dict.fromkeys(round(v,4) for v in [value*2,value+5,value+10,value+1,value*3,(1+value)/2]) if ok(v) and v>value]
    rng=random.Random(int(hashlib.sha256(stem.encode('utf-8')).hexdigest()[:12],16))
    under=min(rng.randrange(5),len(below))
    if 4-under>len(above):under=4-len(above)
    vals=below[:under]+above[:4-under]
    fmt=lambda v:f'{v:g}'
    return make(stem,fmt(value),[fmt(x) for x in vals],explanation,visual,evidence)

def match(stem, pairs, variant):
    # Choose different biological examples in each form, then permute labels. The same three pairs as before, but the
    # right column in any of six orders (match_k): rotating it only made the key one of three cyclic codes.
    return match_k(stem, pairs, variant)

def choose(stem, facts, variant, wrong, visual=None):
    name,correct,why=facts[variant%len(facts)]
    return make(stem.format(x=name),correct,[x for x in wrong if x!=correct][:4],why,visual)

