# ---------------------------------------------------------------------------------------------------------------
# Templates that fill four or more slots across the 21 forms (2026-11-13, finding H4 in docs/MOCK_REVIEW.md).
# item() keys its versions on the variant alone, so a template used in seven slots repeated three items up to seven
# times. These templates follow k = 3·(the template's slots so far) + variant index instead, and each has at least as
# many versions as it has slots, so no item appears in more than three forms. Case endings are written onto the noun
# (Шошны, Хонины, Нафталины), never hyphenated for the converter to fix.
# ---------------------------------------------------------------------------------------------------------------

GROUPS={'plantkey':'plantgroups','enzymes':'digestion','hydrolysis':'digestion','nutrition':'mineral',
        'bloodvessel':'heartvessel','heart':'heartvessel','pressure':'heartvessel','lung':'airway'}
ANIMALS_GEN=['Туулайн','Далайн гахайн','Хонины','Нохойн','Морины','Үхрийн','Тэмээний','Хүний']
PLANTS_GEN=['Шошны','Хулууны','Наранцэцгийн','Вандуйн','Улаан лоолийн','Төмсний']

def seeded(*parts):
    return random.Random(int(hashlib.sha256('|'.join(map(str,parts)).encode('utf-8')).hexdigest()[:12],16))

def pick4(correct, pool, k):
    """Four distractors from the pool; one is at least as long as the key whenever the pool allows."""
    candidates=[x for x in dict.fromkeys(pool) if x!=correct]
    rng=seeded(correct,k)
    longer=[x for x in candidates if len(x)>=len(correct)]
    if not longer:return rng.sample(candidates,4)
    first=rng.choice(longer)
    return [first]+rng.sample([x for x in candidates if x!=first],3)

def match_k(stem, pairs, k):
    """match() with the three pairs taken from k, so a long list gives new items.

    match() only rotates the right column, so its key is always one of three cyclic codes and 1c, 2b, 3a never
    appears. Here the right column takes any of the six orders and the four distractors are drawn from the other five."""
    size=len(pairs);offset=k%size
    selected=[pairs[(offset+i)%size] for i in range(3)]
    assert len({p[1] for p in selected})==3,(stem,selected)
    orders=list(itertools.permutations(range(3)))
    rng=seeded(stem,k,[p[0] for p in selected])
    left=[p[0] for p in selected];right=[selected[i][1] for i in rng.choice(orders)]
    correct=tuple(right.index(p[1]) for p in selected)
    fmt=lambda p:', '.join(f'{i+1}{"abc"[j]}' for i,j in enumerate(p))
    wrong=[fmt(p) for p in rng.sample([p for p in orders if p!=correct],4)]
    return make(stem+'\n'+'\n'.join(f'{i+1}. {s}' for i,s in enumerate(left))+'\n'+'\n'.join(f'{"abc"[i]}. {s}' for i,s in enumerate(right)),
        fmt(correct),wrong,'; '.join(f'{a}: {b}' for a,b in selected)+'.',
        table(['№','Бүтэц / жишээ'],[[i+1,s] for i,s in enumerate(left)]))

def choose_k(stem, facts, k, pool, visual=None):
    fact=facts[k%len(facts)]
    return make(stem.format(x=fact[0]),fact[1],pick4(fact[1],pool,k),fact[2],visual(fact) if callable(visual) else visual)

