        return numeric(f'Судалгааны {area} га талбайд {count} ширхэг {species[k%len(species)]} тоологдов. Нягтшил хэдэн бодгаль/га вэ?',
            density,f'Нягтшил = N/S = {count}/{area} = {density}.',table(['Талбай / га','Нийт бодгаль'],[[area,count]]),
            {'operation':'divide','operands':[count,area],'result':density})
