def template_slots():
    """Each (year, number) that item() or item_k() fills, mapped to that template's running slot count across the years."""
    counts={};slots={}
    for year,skills in MAPS.items():
        for number,skill in enumerate(skills,1):
            if refined(year,number,1) or specialized(year,number,1):
                continue
            group=GROUPS.get(skill,skill)
            slots[(year,number)]=counts.get(group,0)
            counts[group]=counts.get(group,0)+1
    return slots


