def subtask(label, prompt, answer, explanation, points=1):
    return {'id':label,'prompt':prompt,'answer':str(answer),'points':points,'explanation':explanation}

def matching_task(number, title, pairs, variant, extras=None, visual=None):
    pairs=list(pairs)
    rng=random.Random(100*number+variant)
    rng.shuffle(pairs)
    choices=[p[1] for p in pairs]+list(extras or [])
    rng.shuffle(choices)
    parts=[subtask('abcdef'[i],a,choices.index(b)+1,a+' → '+b+'.') for i,(a,b) in enumerate(pairs)]
    return {'id':f'2.{number}','type':'matching','points':6,'topic':title,
            'prompt':title+'\n(a–f)-ийг 1–'+str(len(choices))+' сонголттой зөв тохируул. Сонголт бүрийг нэг удаа хэрэглэнэ.',
            'choices':{str(i+1):x for i,x in enumerate(choices)},'parts':parts,
            'visual':visual or table(['Тэмдэг','Өгөгдөл'],[['abcdef'[i],p[0]] for i,p in enumerate(pairs)])}

def genetics_terms(v,number=2):
    pairs=[('Нэг локусын хоёр ижил аллель','Гомозигот'),('Нэг локусын хоёр өөр аллель','Гетерозигот'),('Хромосом дээрх генийн байрлал','Локус'),('Aa × Aa-ийн генотипийн харьцаа','1:2:1'),('Эр, эм гаметуудын боломжит хослолын хүснэгт','Пеннетийн тор'),('Нэг ген хоёроос олон аллельтэй байх','Олон аллельт')]
    # The examples differ between variants while retaining the six concepts.
    a,b,c=[('AA','Aa','aa'),('BB','Bb','bb'),('DD','Dd','dd')][v-1]
    pairs[0]=(f'{a} эсвэл {c} генотипийн нэр','Гомозигот')
    pairs[1]=(f'{b} генотипийн нэр','Гетерозигот')
    pairs[3]=(f'{b} × {b}-ийн генотипийн харьцаа','1:2:1')
    return matching_task(number,'Генетикийн нэр томьёо',pairs,v,['3:1','Фенотип'])

def respiration_matching(v,number=1):
    pairs=[('Глюкоз хоёр пируват болох','Гликолиз'),('Пируват ацетил-КоА болох','Холбох урвал'),('Ацетил-КоА исэлдэж циклд орох','Кребсийн мөчлөг'),('O₂ электрон хүлээн авч ус үүсэх','Электрон дамжуулах хэлхээ'),('Гликолиз явагдах орчин','Цитозоль'),('Кребсийн мөчлөг явагдах орчин','Митохондрийн матрикс')]
    return matching_task(number,'Аэроб амьсгалын үйл явц, байрлал',pairs,v,visual=scheme(['Глюкоз','Пируват','Ацетил-КоА','Мөчлөг','Электрон дамжуулалт','АТФ']))

def chi_task(v,number=2,ratio=(3,1),kinds=None):
    # Integer expected counts, and small deviations comparable to the source tasks.
    if len(ratio)==2:
        total=[240,320,400][v-1];dev=[6,8,10][v-1]
        expected=[total*r/sum(ratio) for r in ratio]
        observed=[expected[0]-dev,expected[1]+dev]
        chi=sum((o-e)**2/e for o,e in zip(observed,expected))
        answers=[observed[1],expected[0],dev,dev*dev,float(half_up(dev*dev/expected[0])),float(half_up(chi))]
        prompts=['Ажиглагдсан рецессив бодгалийн тоо','Хүлээгдсэн доминант бодгалийн тоо','Рецессив O−E','Доминант (O−E)²','Доминант (O−E)²/E (0.01 хүртэл)','χ² нийт (0.01 хүртэл)']
    else:
        total=[200,240,280][v-1]
        expected=[total*r/sum(ratio) for r in ratio]
        observed=[expected[0]+5,expected[1]-2,expected[2]-3]
        chi=sum((o-e)**2/e for o,e in zip(observed,expected))
        answers=[float(half_up(chi)),len(ratio)-1,5.99,expected[0],expected[1],expected[2]]
        prompts=['χ² нийт (0.01 хүртэл)','Чөлөөний зэрэг','p=0.05 түвшний хүснэгтийн босго','I фенотипийн E','II фенотипийн E','III фенотипийн E']
    names=kinds or ['Доминант','Рецессив']
    if len(names)!=len(ratio):names=['I','II','III']
    rows=[[names[i],int(observed[i]),r] for i,r in enumerate(ratio)]
    visual=table(['Фенотип','Ажиглагдсан O','Онолын жин'],rows)
    return {'id':f'2.{number}','type':'numeric','topic':'Хи-квадрат','points':6,
            'prompt':f'{["Буурцагны үр","Эрдэнэ шишийн үр","Цэцгийн үр"][v-1]}-ийн туршилтын хүснэгтээр χ²=Σ(O−E)²/E тооц. E=N×онолын жин/жингийн нийлбэр. Тоог зөвхөн эцэст нь 0.01 хүртэл тоймло. df=ангиллын тоо−1. p=0.05 босго: df1=3.84, df2=5.99, df3=7.81.',
            'parts':[subtask('abcdef'[i],p,a,f'O = {nums(observed)}; E = {nums(expected)}; χ² = {round(chi,6):g} ≈ {half_up(chi)}.') for i,(p,a) in enumerate(zip(prompts,answers))],
            'visual':visual,'calculation':{'operation':'chi_square','observed':observed,'expected':expected,'result':chi}}

def pedigree(v,number=3):
    genotype=['Aa','Bb','Dd'][v-1];dominant=genotype[0];recessive=genotype[1]
    visual=svg('<path d="M260 100 H520 M390 100 V160 M180 160 H620 M180 160 V215 M390 160 V215 M620 160 V215" fill="none" stroke="#111" stroke-width="3"/>'
        '<rect x="225" y="65" width="70" height="70" fill="white" stroke="#111"/><circle cx="520" cy="100" r="35" fill="white" stroke="#111"/>'
        '<circle cx="180" cy="250" r="35" fill="#111" stroke="#111"/><rect x="355" y="215" width="70" height="70" fill="white" stroke="#111"/><circle cx="620" cy="250" r="35" fill="white" stroke="#111"/>'
        '<text x="230" y="45">I-1</text><text x="500" y="45">I-2</text><text x="150" y="315">II-1</text><text x="355" y="315">II-2</text><text x="595" y="315">II-3</text>')
    prompts=[('a','I-1-ийн генотипийн код',2),('b','Эцэг эхийн дараагийн хүүхэд рецессив байх [bc]%: b',2),('c','Эцэг эхийн дараагийн хүүхэд рецессив байх [bc]%: c',5),('d','II-1-ийн генотипийн код',3),('e','II-1 нь тээгчтэй хосолбол рецессив үр төл гарах [ef]%: e',5),('f','II-1 нь тээгчтэй хосолбол рецессив үр төл гарах [ef]%: f',0)]
    return {'id':f'2.{number}','type':'pedigree','topic':'Аутосомын рецессив удамшил','points':6,
            'prompt':f'Зурагт будагдсан бодгаль {recessive*2} аутосомын рецессив шинжтэй. Эцэг эх эрүүл. Мутаци, фенокопи байхгүй. Генотипийн код: 1={dominant*2}, 2={genotype}, 3={recessive*2}. Магадлалыг [bc]%, [ef]% хоёр оронтой тооны цифрээр бөглө.',
            'parts':[subtask(a,p,ans,'Эрүүл эцэг эхээс рецессив хүүхэд төрсөн тул хоёул тээгч. Гетерозиготын хослол 1:2:1; aa × Aa үед 1/2 рецессив.') for a,p,ans in prompts],
            'visual':visual}

def part2(year,v):
    pollution=[('Нүүрстөрөгчийн дутуу исэл','O₂ зөөх чадварыг бууруулна'),('SO₂','Хүчиллэг хур тунадас'),('Нитрат, фосфат','Эвтрофикаци'),('Мөнгөн ус','Мэдрэлийн тогтолцооны хор'),('Чанга дуу','Сонсголын гэмтэл'),('Ионжуулагч цацраг','ДНХ гэмтэх эрсдэл')]
