def refined(year,n,v):
    if (year,n)==(2021,40):
        cross=['IAIB × ii','IAIB × IAi','IAIB × IBi'][v-1];answer=[0,25,25][v-1]
        return numeric(f'АВО тогтолцоонд {cross} хосоос IV бүлгийн цустай хүүхэд төрөх магадлал хэдэн хувь вэ?',answer,f'Гаметуудын боломжит хослолыг тооцвол IAIB генотипийн магадлал {answer}%.',scheme([cross,'Гамет','Хүүхдийн бүлэг']))
    if (year,n)==(2022,39):
        target=['I, II, III, IV дөрвөн бүлэг','Зөвхөн II ба IV','Зөвхөн III ба IV'][v-1]
        correct=['IAi × IBi','IAIA × IBi','IBIB × IAi'][v-1]
        return make(f'Хүүхдүүд нь {target}-тэй төрөх боломжтой эцэг эхийн хослол аль вэ?',correct,[x for x in ['IAi × IBi','IAIA × IBi','IBIB × IAi','ii × ii','IAIA × ii'] if x!=correct],f'{correct} хослолын гаметуудыг нэгтгэхэд {target} үүснэ.')
    if (year,n)==(2023,40):
        child=['IV','I','II'][v-1];correct=['IAIA × IBIB','IAi × IBi','IAIA × ii'][v-1]
        wrong=[['ii × ii','IAIA × ii','IBIB × ii','IAIA × IAIA'],['IAIA × IBIB','IAIA × ii','IBIB × ii','IAIB × IAIB'],['IBIB × ii','IBIB × IBIB','ii × ii','IAIB × IBIB']][v-1]
        return make(f'Нярай {child} бүлгийн цустай. Доорх гэр бүлүүдээс аль нь энэ хүүхдийн биологийн эцэг эх байх боломжтой вэ?',correct,wrong,'Хүүхэд нэг аллелийг эхээс, нэгийг эцгээс авна; АВО-ийн аллелийн хослолыг шалгана.')
