def input_figure(skill,v):
    """Additional original input diagrams; never expose a correct option as a label."""
    if skill=='temperature':
        return plot([('Орчны t°',[20,24,28,32,36]),('Биеийн t°',[37,37,37,37,37])],[0,5,10,15,20],'Температур / °C','Хугацаа / мин')
    if skill=='glucose':
        values=[4.5,6,7,5.5,4.5] if v!=2 else [5,4.5,4,3.5,3]
        return plot([('Цусны глюкоз',values)],[0,15,30,45,60],'Глюкоз / ммоль·л⁻¹','Хугацаа / мин')
    if skill=='xerophyte':
        return svg('<path d="M80 230 Q430 15 800 230 Q430 330 80 230" fill="#eee" stroke="#111" stroke-width="6"/>'
            '<path d="M170 220 Q430 80 700 220" fill="none" stroke="#777" stroke-width="3"/>'
            '<path d="M370 265 V220 H420 V265 M500 265 V220 H550 V265" fill="white" stroke="#111" stroke-width="3"/>'
            '<text x="80" y="35">Хуурай орчны навчны хөндлөн огтлолын бүдүүвч</text>')
    if skill=='population':
        return table(['Талбай / га','Нийт бодгаль'],[[3+(v-1),180+20*(v-1)]])
    if skill=='fungi':
        return svg('<path d="M200 290 V170 l-100 -70 M200 190 l100 -90 M200 235 l160 -40 M200 260 l-100 -20" fill="none" stroke="#111" stroke-width="12"/>'
            '<circle cx="100" cy="90" r="45" fill="#eee" stroke="#111"/><circle cx="300" cy="90" r="45" fill="#eee" stroke="#111"/>'
            '<circle cx="360" cy="190" r="32" fill="#eee" stroke="#111"/><text x="470" y="100">Гиф</text><text x="470" y="150">Спор үүсэх хэсэг</text>')
    if skill=='gastransport':return scheme(['Уушги','Цус','Эд'])
    if skill=='anaerobic':return scheme([['Булчингийн эс','Хөрөнгө','Сүүн хүчлийн бактер'][v-1],'Глюкоз','O₂-гүй → X'])
    if skill=='immunity':return scheme([['Вакцин','Эхээс ирсэн уураг','Халдвар'][v-1],'Хүлээн авагч бие','Хамгаалалт'])
    if skill=='rna':return scheme(['Нуклеотид','Дан полимер гинж','Уураг нийлэгжил'])
    if skill=='eye':
        return svg('<ellipse cx="240" cy="170" rx="180" ry="105" fill="none" stroke="#111"/><circle cx="240" cy="170" r="65" fill="#ddd" stroke="#111"/><circle cx="240" cy="170" r="22" fill="#111"/>'
            '<ellipse cx="680" cy="170" rx="180" ry="105" fill="none" stroke="#111"/><circle cx="680" cy="170" r="65" fill="#ddd" stroke="#111"/><circle cx="680" cy="170" r="48" fill="#111"/>'
            '<text x="160" y="315">Гэрэлтэй</text><text x="610" y="315">Харанхуй</text>')
    if skill=='dna':return table(['Суурь','A','T','G','C'],[['Хувь', [15,25,35][v-1],'?','?','?']])
    if skill=='mollusc':
        if v==1:
            return svg('<ellipse cx="440" cy="100" rx="70" ry="65" fill="#eee" stroke="#111"/>'+''.join(f'<path d="M{405+i*10} 150 Q{250+i*40} 270 {270+i*50} 290" fill="none" stroke="#111" stroke-width="9"/>' for i in range(8)))
        if v==2:return svg('<path d="M180 280 Q50 10 430 40 Q800 60 680 280 Z" fill="#eee" stroke="#111" stroke-width="3"/>'+''.join(f'<path d="M430 270 L{200+i*55} 80" stroke="#777"/>' for i in range(8)))
        return svg('<path d="M110 265 Q400 220 720 265 l80 -55 m-90 55 l80 -15" fill="none" stroke="#111" stroke-width="8"/><circle cx="410" cy="150" r="105" fill="#eee" stroke="#111"/><path d="M400 155 c-70 -70 90 -100 80 0 c-10 90 -120 70 -120 -10" fill="none" stroke="#111" stroke-width="4"/>')
    return None

def reference_points(year):
    if year<=2023:
        bank=json.loads((ROOT/str(year)/'reference/bank-A.json').read_text(encoding='utf-8'))
        selected={}
        for entry in bank['entries']:
            selected.setdefault(entry['number'],entry)
        weights=[selected[n]['points'] for n in range(1,51)]
        # The legacy bank is inconsistent (2020=74, 2021=75). These house
        # adjustments are disclosed; they are NOT described as official marks.
        if year==2020:
            for index in [39,41]:weights[index-1]+=1
        if year==2021:weights[39-1]+=1
        return weights, selected
    if year==2024:
        twos={3,4,6,7,9,10,11,12,13,16,17,18,21,22,23,27,29,31,33,34,37,38,41,42,47,48}
        return [2 if n in twos else 1 for n in range(1,51)], {}
    import re
    import pymupdf
    document=pymupdf.open(ROOT/str(year)/'reference/official-A.pdf')
    points=[int(x) for page in list(document)[:14] for x in re.findall(r'\[(\d)\s*оноо\]',page.get_text())]
    return points, {}

def build():
    manifest={'subject':'biology','language':'mn','createdAt':'2026-11-08','author':'Codex (GPT-6)',
              'websiteIntegrated':False,'years':[],'answerSource':'Authored and calculated by Codex; not an official key.',
              'reviewStatus':'DRAFT: teacher review and empirical difficulty calibration pending.'}
    slots=template_slots()
    for year,skills in MAPS.items():
        points,selected=reference_points(year)
        assert len(skills)==len(points)==(46 if year==2026 else 50),(year,len(skills),len(points))
        assert sum(points)==76,(year,sum(points))
        source=SOURCES[year]
        out=ROOT/str(year)
        if (out/'reference'/'official-A.pdf').exists():
            source['pdfSha256']=hashlib.sha256((out/'reference'/'official-A.pdf').read_bytes()).hexdigest()
        write_json(out/'reference'/'source-record.json',{'year':year,'variant':'A','retrievedAt':'2026-11-08',**source})
        blueprint={'year':year,'referenceVariant':'A','reference':source,'durationMinutes':80,
                   'durationEvidence':'EEC biology sitting guidance; duration is not printed on all papers.',
                   'partI':{'questionCount':len(skills),'points':76,'items':[
                       {'number':i,'points':p,'authoringSkill':s,
                        'sourceBankPoints':selected.get(i,{}).get('points'),
                        'pointsProvisional':year in [2020,2021],
                        'sourceBankId':selected.get(i,{}).get('bankId'),
                        'referenceHadImage':bool('<img ' in selected.get(i,{}).get('html',''))}
                       for i,(s,p) in enumerate(zip(skills,points),1)]},
                   'partII':{'taskCount':4,'points':24,'provisional':year in [2020,2021,2023]},
                   'fidelityStatus':'Draft parallel practice, not certified equivalent. Some source slots are adapted at topic level.'}
        write_json(out/'blueprint.json',blueprint)
        forms=[]
        for v in range(1,4):
            figure_dir=out/'images'/f'mock-{v:02d}'
            questions=[]
            for number,(skill,weight) in enumerate(zip(skills,points),1):
                k=3*slots.get((year,number),0)+(v-1)
                question=refined(year,number,v) or specialized(year,number,v) or item_k(skill,k,year,v) or item(skill,v,year)
                question['id']=f'{number}'
                question['type']='multiple-choice'
                question['points']=weight
                question['skill']=skill
                question['referenceItem']=str(number)
                question['referenceMatch']='topic-level adaptation; exact cognitive equivalence not certified'
                correct=question.pop('correctText')
                options=[correct]+question.pop('wrong')
                random.Random(year*10000+v*100+number).shuffle(options)
                question['options']=dict(zip(LETTERS,options))
                question['answer']=LETTERS[options.index(correct)]
                question['answerText']=correct
                # A figure is bundled for every slot, including all source image slots.
                # Where a recovered image is missing, use a newly drawn context diagram;
                # this does not claim to reproduce the original visual task.
                visual=question.pop('visual') or input_figure(skill,v)
                if visual:
                    question['figureRole']='original task diagram or data table'
                    figure_dir.mkdir(parents=True,exist_ok=True)
                    filename=f'q-{number:02d}.svg'
                    (figure_dir/filename).write_text(visual,encoding='utf-8')
                    question['figure']={'path':f'images/mock-{v:02d}/{filename}','alt':'Даалгаврын зохиомол бүдүүвч / өгөгдлийн зураг','origin':'Original SVG authored by Codex.'}
                if blueprint['partI']['items'][number-1]['referenceHadImage'] and not visual:
                    question['referenceImageGap']='Source was visual; this adaptation currently has no corresponding figure.'
                if question.get('calculation') is None:question.pop('calculation',None)
                questions.append(question)
            figure_dir.mkdir(parents=True,exist_ok=True)
            tasks=part2(year,v)
            for i,task in enumerate(tasks,1):
                visual=task.pop('visual')
                filename=f'task-2-{i}.svg'
                (figure_dir/filename).write_text(visual,encoding='utf-8')
                task['figure']={'path':f'images/mock-{v:02d}/{filename}','alt':task['topic']+' — өгөгдлийн зураг','origin':'Original SVG authored by Codex.'}
                task['referenceItem']=f'2.{i}'
            exam={'schemaVersion':1,'subject':'biology','language':'mn','referenceYear':year,'mockVariant':f'B{v}',
                  'title':f'Биологи · {year} оны загвар · B{v}','official':False,'author':'Codex (GPT-6)',
                  'referenceVariant':'A','reference':source,'durationMinutes':80,'totalPoints':100,
                  'difficulty':{'target':'Same level as reference; change contexts, not intended difficulty',
                                'verified':False,'note':'Teacher review and student-based equating have not been performed.'},
                  'completionStatus':'draft-requires-reference-and-fidelity-review',
                  'limitations':source['gaps']+['Some MCQ slots are topic-level adaptations, not exact parallel items.','Part II response packaging may differ from official digit grouping.'],
                  'answerProvenance':'Answers and explanations authored by Codex (GPT-6); unofficial. No reference-site answer CSS used.',
                  'instructions':['80 минут. Нийт 100 оноо.','I хэсгийн даалгавар бүрт A–E-ээс нэг хариу сонго.','II хэсэгт хариуг өгөгдсөн нэгж, нарийвчлалаар бич.','Зураг нь бодит хэмжээсээр биш.','Энэ бол хянан магадлаагүй бэлтгэлийн хувилбар.'],
                  'sections':[{'id':'I','title':'Сонгох даалгавар','points':76,'questions':questions},
                              {'id':'II','title':'Задгай / харгалзуулах даалгавар','points':24,'tasks':tasks}]}
            path=out/f'mock-{v:02d}.json'
            write_json(path,exam)
            forms.append({'path':str(path.relative_to(ROOT)).replace('\\','/'),'sha256':hashlib.sha256(path.read_bytes()).hexdigest()})
        manifest['years'].append({'year':year,'variantCount':3,'reference':source,'forms':forms})
    write_json(ROOT/'manifest.json',manifest)
    print('Wrote 21 draft forms, 1,038 MCQ, 84 tasks / 504 subanswers.')

if __name__=='__main__':
    build()
